INSERT INTO `categories` VALUES ('cat-accessories','Phụ kiện cao cấp','phu-kien-cao-cap','Dock Thunderbolt, sạc GaN siêu nhanh và giải pháp kết nối hiệu năng đỉnh cao.','Cpu','hub',3),('cat-audio','Âm thanh & Loa','am-thanh-loa','Trải nghiệm âm thanh trung thực chuẩn phòng thu với công nghệ chống ồn tiên tiến.','Headphones','audio',0),('cat-smarthome','Gia dụng thông minh','gia-dung-thong-minh','Hệ sinh thái tự động hóa và an ninh chuẩn mực cho phong cách sống hiện đại.','Home','camera',4),('cat-watches','Đồng hồ & Vòng đeo','dong-ho-vong-deo','Chất liệu Titanium chuẩn hàng không vũ trụ và cảm biến đo chỉ số sinh trắc chính xác.','Watch','watch',1),('cat-workspace','Bàn làm việc & Ánh sáng','ban-lam-viec-anh-sang','Kiến tạo không gian làm việc tối giản, công thái học và chuẩn thẩm mỹ Bắc Âu.','Lamp','lamp',2);
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;
