g','2026-09-28 02:28:00','2026-09-28 02:28:00'),(67,'AUR-9767','user-04','Đặng Tuấn Anh','0933221100','tuananh.dang@fintech.vn','Hồ Chí Minh','Quận 7','Phường Tân Phong','Khu biệt thự Phú Mỹ Hưng',NULL,15980000,0,0,NULL,15980000,'cod','pending',NULL,'pending','2026-09-28 08:13:00','2026-09-28 08:13:00'),(68,'AUR-9768','user-04','Đặng Tuấn Anh','0933221100','tuananh.dang@fintech.vn','Hồ Chí Minh','Quận 7','Phường Tân Phong','Khu biệt thự Phú Mỹ Hưng',NULL,16800000,0,0,NULL,16800000,'credit_card','paid','2026-09-28 11:30:00','confirmed','2026-09-28 11:05:00','2026-09-28 11:30:00'),(69,'AUR-9769','user-05','Phạm Thanh Thảo','0977889900','thanhthao.pham@studio.design','Hồ Chí Minh','Quận Bình Thạnh','Phường 22','208 Nguyễn Hữu Cảnh, Tòa Landmark 81',NULL,3490000,30000,349000,'AURAXIN',3171000,'cod','pending',NULL,'pending','2026-09-28 15:10:00','2026-09-28 15:10:00');
/*!40000 ALTER TABLE `orders` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(220) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price` int unsigned NOT NULL,
  `original_price` int unsigned DEFAULT NULL,
  `stock` int unsigned NOT NULL DEFAULT '0',
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `specs` json NOT NULL,
  `features` json NOT NULL,
  `images` json NOT NULL,
  `colors` json NOT NULL,
  `capacities` json NOT NULL,
  `illustration_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'audio',
  `badge` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_best_seller` tinyint(1) NOT NULL DEFAULT '0',
  `is_new` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_slug` (`slug`),
  UNIQUE KEY `uq_products_sku` (`sku`),
  KEY `idx_products_category` (`category_id`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES ('prod-01','Tai nghe chống ồn AURA Studio Pro ANC','tai-nghe-aura-studio-pro-anc','AUR-HP-01','cat-audio',7890000,8990000,28,'Được chế tác từ nhôm nguyên khối hàng không và da protein cao cấp, AURA Studio Pro mang đến chất âm hi-res đỉnh cao, công nghệ khử ồn chủ động 40dB và thời lượng pin 45 giờ liên tục.','{\"Pin\": \"45 giờ (ANC Bật)\", \"Driver\": \"40mm Titanium Custom\", \"Kết nối\": \"Bluetooth 5.4, aptX Lossless, Type-C 24bit/96kHz\", \"Chống ồn\": \"Active Noise Cancelling 4 mic kép\", \"Trọng lượng\": \"248g\"}','[\"Chất âm Hi-Res Studio đẳng cấp chuẩn audiophile\", \"Khử tiếng ồn thích ứng theo thời gian thực\", \"Đệm tai Memory Foam thoáng khí êm ái cả ngày\", \"Sạc nhanh 10 phút nghe 5 giờ\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.3.jpg/960px-Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\", \"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.4.jpg/960px-Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\", \"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.5.jpg/960px-Sony-WH-1000XM3-kabellose-Bluetooth-Noise-Cancelling-Kopfhoerer.5.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Đen Titan Obsidian\", \"Bạc Ánh Trăng Lunar\", \"Xám Đậm Space Gray\"]','[]','audio','Bán chạy nhất',1,1,0,1,'2026-08-15 10:00:00'),('prod-02','Đồng hồ thông minh AURA Chrono Titanium Ultra','dong-ho-aura-chrono-titanium-ultra','AUR-WT-02','cat-watches',11490000,12990000,15,'Vỏ Titanium Cấp 5 siêu bền, mặt kính Sapphire chống trầy tuyệt đối cùng màn hình LTPO AMOLED 2000 nits. Đồng hành cùng bạn trong mọi chuyến thám hiểm và theo dõi sức khỏe chuyên sâu.','{\"Màn hình\": \"1.43 inch LTPO AMOLED, 2000 nits, Sapphire Glass\", \"Cảm biến\": \"ECG, SpO2 quang phổ kép, GPS tần số kép L1+L5\", \"Chống nước\": \"10ATM / 100m chuẩn thợ lặn\", \"Chất liệu vỏ\": \"Titanium Grade 5 siêu nhẹ\", \"Thời lượng pin\": \"14 ngày sử dụng tiêu chuẩn\"}','[\"Vỏ Titanium Cấp 5 bền bỉ chịu mọi điều kiện khắc nghiệt\", \"Đo điện tâm đồ ECG và cảnh báo nhịp tim bất thường\", \"GPS tần số kép định vị chuẩn xác từng mét\", \"Thời lượng pin vượt trội lên tới 14 ngày\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Huawei_Smartwatch_Fit_2.jpg/960px-Huawei_Smartwatch_Fit_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Titanium Tự Nhiên\", \"Đen DLC Carbon\", \"Vàng Cát Safari\"]','[]','watch','Mới ra mắt',1,0,1,1,'2026-09-01 08:00:00'),('prod-03','Đèn bàn công thái học AURA Lumina Arc','den-ban-aura-lumina-arc','AUR-LP-03','cat-workspace',2650000,3100000,42,'Kiệt tác chiếu sáng tối giản dành cho không gian làm việc chuyên nghiệp. Quang phổ ánh sáng tự nhiên Ra≥98 giảm mỏi mắt tuyệt đối, điều khiển cảm ứng không chạm và xoay đa trục mượt mà.','{\"Công suất\": \"18W LED Ultra-EyeCare\", \"Chất liệu\": \"Nhôm Anodized 6063 cao cấp\", \"Điều khiển\": \"Cảm biến không chạm & núm xoay kim loại vô cực\", \"Nhiệt độ màu\": \"2700K - 6500K tùy biến\", \"Chỉ số hoàn màu\": \"CRI Ra ≥ 98\"}','[\"Ánh sáng mô phỏng mặt trời tự nhiên không gây hại mắt\", \"Điều chỉnh độ sáng và nhiệt độ màu mượt mà\", \"Cần đèn nhôm công nghệ khớp quay thủy lực tĩnh âm\", \"Tích hợp cổng sạc Type-C PD 20W ở chân đế\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Desk_Lamp_1_2013-07-12.jpg/960px-Desk_Lamp_1_2013-07-12.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Đen Mờ Matte Black\", \"Bạc Nhôm Silver\", \"Trắng Bắc Âu Arctic\"]','[]','lamp','Yêu thích',1,1,0,1,'2026-07-20 14:30:00'),('prod-04','Loa không dây cao cấp AURA Horizon Hi-Fi 360°','loa-khong-day-aura-horizon-hi-fi','AUR-SP-04','cat-audio',9200000,NULL,19,'Hệ thống âm thanh đa hướng 360 độ với 6 củ loa neodymium và subwoofer hướng sàn, tái tạo trường âm rộng mở, giàu nhạc tính và độ chi tiết ấn tượng ở mọi góc phòng.','{\"Driver\": \"1x Subwoofer 4.5\\\", 3x Midrange 2\\\", 2x Silk Dome Tweeter\", \"Kết nối\": \"AirPlay 2, Spotify Connect, Bluetooth 5.3, Wi-Fi 6\", \"Công suất\": \"120W RMS High-Output\", \"Chất liệu\": \"Vải len Kvadrat Đan Mạch & Gỗ Sồi tự nhiên\"}','[\"Trường âm 360 độ ngập tràn căn phòng\", \"Vật liệu len dệt cao cấp bền đẹp theo năm tháng\", \"Hỗ trợ kết nối âm thanh đa phòng Multi-room không độ trễ\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Sonos_PLAY_1_wireless_speaker.jpg/960px-Sonos_PLAY_1_wireless_speaker.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Gỗ Sồi Tự Nhiên & Len Xám\", \"Gỗ Óc Chó & Len Đen\"]','[]','speaker','Premium Edition',1,0,1,1,'2026-08-28 09:00:00'),('prod-05','Bàn phím cơ không dây AURA Precision 75 Gasket','ban-phim-co-aura-precision-75','AUR-KB-05','cat-workspace',3490000,3990000,35,'Thiết kế CNC nhôm nguyên khối, cấu trúc Gasket-mount 5 lớp tiêu âm đem lại cảm giác gõ thock êm ái, switch bôi trơn sẵn từ nhà máy và kết nối 3 chế độ siêu nhạy.','{\"Pin\": \"8000mAh (dùng tới 200 giờ)\", \"Keycap\": \"PBT Double-shot Cherry Profile\", \"Layout\": \"75% nhỏ gọn (82 phím)\", \"Switch\": \"AURA Crystal Linear Pre-lubed (45g)\", \"Cấu trúc\": \"Full CNC Nhôm, Gasket Mount 5 lớp Poron\"}','[\"Vỏ nhôm CNC phay tinh xảo với trọng lượng đầm tay 1.8kg\", \"Âm thanh gõ trầm ấm mượt mà không cần mod thêm\", \"Núm xoay kim loại đa chức năng điều khiển âm lượng\", \"Hotswap 5 pin thay switch nhanh chóng\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Mechanical_Keyboard.jpg/960px-Mechanical_Keyboard.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Xám Bão Stormy\", \"Đen Huyền Bí Anodized\", \"Trắng Băng Ice White\"]','[]','keyboard','Hot Deal',0,1,0,1,'2026-08-01 11:20:00'),('prod-06','Trạm kết nối Thunderbolt 4 AURA Pro Hub 12-in-1','tram-ket-noi-aura-pro-hub-12-in-1','AUR-HB-06','cat-accessories',4290000,NULL,22,'Giải pháp mở rộng kết nối toàn diện cho các nhà sáng tạo nội dung và lập trình viên. Hỗ trợ xuất 2 màn hình 4K@120Hz hoặc 1 màn hình 8K, sạc PD 100W và tản nhiệt buồng hơi thụ động siêu êm.','{\"Sạc\": \"Power Delivery 100W cho Laptop\", \"Mạng\": \"Ethernet 2.5 Gigabit siêu tốc\", \"Băng thông\": \"Thunderbolt 4 / USB4 lên tới 40Gbps\", \"Cổng xuất hình\": \"2x HDMI 2.1, 1x DisplayPort 1.4\"}','[\"Băng thông truyền tải dữ liệu 40Gbps cực đại\", \"Hỗ trợ 2 màn hình ngoài độ phân giải cao sắc nét\", \"Vỏ nhôm tản nhiệt nguyên khối không quạt ồn\"]','[\"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Delock_USB_m.2_NVMe_docking_station-oblique_FS_PNr%C2%B00912.jpg/960px-Delock_USB_m.2_NVMe_docking_station-oblique_FS_PNr%C2%B00912.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\", \"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Delock_USB_m.2_NVMe_docking_station-top_PNr%C2%B00913.jpg/960px-Delock_USB_m.2_NVMe_docking_station-top_PNr%C2%B00913.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail\"]','[\"Xám Không Gian Space Gray\", \"Bạc Nguyên Bản\"]','[]','hub','Chuyên nghiệp',0,0,1,1,'2026-09-10 16:00:00'),('prod-07','Bàn nâng hạ thông minh AURA Minimalist Walnut','ban-nang-ha-aura-minimalist-walnut','AUR-DK-07','cat-workspace',16800000,18500000,8,'Mặt bàn bằng gỗ óc chó Bắc Mỹ nguyên tấm tuyển chọn, kết hợp khung nâng hạ động cơ kép Đức tải trọng 140kg, bảng điều khiển OLED ghi nhớ 4 nấc chiều cao và cảm biến chống va chạm thông minh.','{\"Chiều cao\": \"62cm - 128cm mượt mà\", \"Động cơ\": \"Dual Motor Bosch Technology, 38mm/s, <40dB\", \"Tải trọng\": \"140kg nâng hạ êm ái\", \"Kích thước\": \"160cm